{"template": "在 {nums} 中，把 {relation_text} {target} 的数写在下面。", "slots": {"nums": {"type": "choice", "options": ["9、6、4、7、3、5、1、10", "10、2、0、7、3、5、4、6", "8、1、5、9、2、6、0、3", "7、4、10、1、8、5、9、2"]}, "relation_text": {"type": "choice", "options": ["大于", "小于"]}, "target": {"type": "int", "min": 1, "max": 9}}, "constraints": [], "verifiable_type": "program", "solver": "def solve(nums, relation_text, target):
