        if n % i == 0:
            factors.append(i)

    # 2. 计算长方形种数 (a*b=n, a<=b)
    rect_count = 0
    for a in range(1, isqrt(n) + 1):
        if n % a == 0:
            rect_count += 1

    # 3. 格式化因数字符串
    factors_str_val = ",".join(map(str, factors))

    # 4. 判断质数还是合数
    # 题目范围 n>=2
    is_prime = True
    if n < 2:
        is_prime = False
    else:
        for i in range(2, isqrt(n) + 1):
            if n % i == 0:
                is_prime = False
                break

