{"template": "计算：{a} + {b} × {c}", "slots": {"a": {"type": "decimal", "min": "0.1", "max": "9.9", "places": 1}, "b": {"type": "fraction", "min": "1/10", "max": "9/10", "max_denominator": 5}, "c": {"type": "decimal", "min": "0.2", "max": "5.0", "places": 1}}, "constraints": ["Fraction(b).denominator in [2, 3, 4, 5]"], "verifiable_type": "program", "solver": "def solve(a, b, c):
    frac_a = Fraction(a)
